package net.civeira.phylax.feature.observe.ingest;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class RateLimiterUnitTest {

  @Test
  @DisplayName("A burst up to the limit passes, the excess is cut and the bucket refills with time")
  void tokenBucket() {
    RateLimiter limiter = new RateLimiter();
    long now = 1_000_000;
    int allowed = 0;
    for (int i = 0; i < 100; i++) {
      if (limiter.allow("api", 60, now)) {
        allowed++;
      }
    }
    Assertions.assertEquals(60, allowed);
    Assertions.assertFalse(limiter.allow("api", 60, now));
    Assertions.assertTrue(limiter.allow("api", 60, now + 2_000));
    Assertions.assertTrue(limiter.allow("other", 60, now));
    Assertions.assertTrue(limiter.allow("api", 0, now));
  }
}
